var n=`0453-sis-kebab`;var r=`world-0453`;var a=`TR`;var o=`western-asia`;var t=4;var s=121;var l={en:`Şiş Kebab`,ua:`Шиш-кебаб`};var g={en:`A traditional dish from Türkiye, centered on lamb, yellow onion, lemon juice, red bell pepper. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: ягнятина, жовта цибуля, лимонний сік, червоний солодкий перець. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`lamb`,700,`g`],[`yellow-onion`,160,`g`],[`extra-virgin-olive-oil`,55,`ml`],[`lemon-juice`,30,`ml`],[`dried-oregano`,5,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:10,i:[[`red-bell-pepper`,250,`g`]]},{en:`Grill over medium-high heat for about 18 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 18 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:18,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var m={slug:n,id:r,country:`TR`,region:o,servings:4,minutes:121,title:l,text:g,steps:d};export{a as country,m as default,r as id,s as minutes,o as region,t as servings,n as slug,d as steps,g as text,l as title};